function groupedBalanceSheet(report) {
  const classes = new Map();
  const add = row => {
    const classCode = row.code.slice(0, 1);
    const groupCode = row.code.slice(0, 2);
    if (!classes.has(classCode)) classes.set(classCode, new Map());
    const groups = classes.get(classCode);
    if (!groups.has(groupCode)) groups.set(groupCode, []);
    groups.get(groupCode).push(row);
  };
  [...report.assets, ...report.liabilities].forEach(add);
  if (report.periodResult) add({ code: '59', name: 'Hesaplanan dönem kârı / zararı',
    value: report.periodResult, synthetic: true });
  return Object.keys(BALANCE_CLASS_NAMES).map(code => {
    const groups = [...(classes.get(code) || new Map())].sort(([a], [b]) => a.localeCompare(b))
      .map(([groupCode, rows]) => ({ code: groupCode,
        name: BALANCE_GROUP_NAMES[groupCode] || 'DİĞER HESAPLAR',
        rows, total: rows.reduce((sum, row) => sum + row.value, 0) }));
    return { code, name: BALANCE_CLASS_NAMES[code], groups,
      total: groups.reduce((sum, group) => sum + group.total, 0) };
  }).filter(group => group.groups.length);
}


// csv.js
function parseCsv(text) {
  const records = [];
  let row = [];
  let field = '';
  let quoted = false;
  const source = text.replace(/^\uFEFF/, '');
  for (let i = 0; i < source.length; i++) {
    const char = source[i];
    if (quoted) {
      if (char === '"' && source[i + 1] === '"') { field += '"'; i++; }
      else if (char === '"') quoted = false;
      else field += char;
    } else if (char === '"') quoted = true;
    else if (char === ',') { row.push(field); field = ''; }
    else if (char === '\n' || char === '\r') {
      if (char === '\r' && source[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some(value => value.trim())) records.push(row);
      row = [];
    } else field += char;
  }
  if (quoted) throw new Error('CSV içinde kapanmamış tırnak işareti var.');
  if (field || row.length) { row.push(field); records.push(row); }
  return records;
}

function parseAccountPlan(text) {
  const rows = parseCsv(text);
  if (!rows.length) throw new Error('Dosya boş.');
  const header = rows.shift().map(value => value.trim());
  const codeIndex = header.indexOf('Hesap Kodu');
  const nameIndex = header.indexOf('Hesap Adı');
  const sideIndex = header.indexOf('Taraf');
  if ([codeIndex, nameIndex, sideIndex].includes(-1))
    throw new Error('CSV dosyasında Hesap Kodu, Hesap Adı ve Taraf başlıkları bulunmalı.');
  const seen = new Set();
  const accounts = rows.map((row, index) => {
    const code = (row[codeIndex] || '').trim();
    const name = (row[nameIndex] || '').trim();
    const side = (row[sideIndex] || '').trim().toUpperCase();
    if (!/^\d{3}$/.test(code)) throw new Error(`${index + 2}. satırda hesap kodu üç haneli olmalı.`);
    if (!name) throw new Error(`${index + 2}. satırda hesap adı boş olamaz.`);
    if (!['B', 'A'].includes(side)) throw new Error(`${index + 2}. satırda Taraf B veya A olmalı.`);
    if (seen.has(code)) throw new Error(`${code} hesabı dosyada birden fazla kez var.`);
    seen.add(code);
    return { code, name, side };
  });
  if (!accounts.length) throw new Error('Dosyada hesap bulunamadı.');
  return accounts.sort((a, b) => a.code.localeCompare(b.code, 'tr'));
}

function validateAccountReplacement(accounts, vouchers) {
  const codes = new Set(accounts.map(item => item.code));
  const missing = [...new Set(vouchers.flatMap(voucher => voucher.lines.map(line => line.code)))].filter(code => !codes.has(code));
  if (missing.length) throw new Error(`Kayıtlı fişlerde kullanılan şu hesaplar yeni planda yok: ${missing.join(', ')}. Plan değiştirilmedi.`);
}


// storage.js
const DB_NAME = 'mini-muhasebe-2026';
const DB_VERSION = 1;
const LOCAL_KEY = 'mini-muhasebe-2026-state';
const FILE_MODE = typeof location !== 'undefined' && location.protocol === 'file:';

function displayBusinessTitle(state) {
  return typeof state?.businessTitle === 'string' && state.businessTitle.trim()
    ? state.businessTitle.trim() : 'muhasebe.info';
}

function withoutVouchers(state) {
  return { ...state, vouchers: [], nextNumber: 1 };
}

function renumberVouchersByDate(state) {
  const vouchers = [...state.vouchers]
    .sort((a, b) => a.date.localeCompare(b.date) || a.number - b.number)
    .map((voucher, index) => ({ ...voucher, number: index + 1 }));
  return { ...state, vouchers, nextNumber: vouchers.length + 1 };
}

function openDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => request.result.createObjectStore('app');
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function readValue(db) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('app', 'readonly');
    const request = transaction.objectStore('app').get('state');
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function loadState() {
  if (FILE_MODE) {
    const saved = localStorage.getItem(LOCAL_KEY);
    if (saved) return validateBackup(JSON.parse(saved));
  }
  const db = FILE_MODE ? null : await openDatabase();
  try {
    const saved = db ? await readValue(db) : null;
    if (saved) return saved;
    let csv;
    if (typeof DEFAULT_ACCOUNT_CSV === 'string') csv = DEFAULT_ACCOUNT_CSV;
    else {
      const response = await fetch('./data/hesap-plani.csv');
      if (!response.ok) throw new Error('Başlangıç hesap planı yüklenemedi.');
      csv = await response.text();
    }
    const accounts = parseAccountPlan(csv);
    const state = { version: 1, year: 2026, accounts, vouchers: [], nextNumber: 1, businessTitle: '' };
    await saveState(state, db);
    return state;
  } finally { db?.close(); }
}

async function saveState(state, existingDb) {
  if (FILE_MODE) {
    localStorage.setItem(LOCAL_KEY, JSON.stringify(state));
    return;
  }
  const db = existingDb || await openDatabase();
  try {
    await new Promise((resolve, reject) => {
      const transaction = db.transaction('app', 'readwrite');
      transaction.objectStore('app').put(state, 'state');
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
      transaction.onabort = () => reject(transaction.error);
    });
  } finally { if (!existingDb) db.close(); }
}

function validateBackup(data) {
  if (!data || data.version !== 1 || data.year !== 2026 || !Array.isArray(data.accounts) ||
      !Array.isArray(data.vouchers) || !Number.isInteger(data.nextNumber) ||
      (data.businessTitle !== undefined && (typeof data.businessTitle !== 'string' || data.businessTitle.length > 100)))
    throw new Error('Yedek dosyası beklenen biçimde değil.');
  const codes = new Set();
  for (const account of data.accounts) {
    if (!/^\d{3}$/.test(account.code) || !account.name || !['A', 'B'].includes(account.side) || codes.has(account.code))
      throw new Error('Yedekte geçersiz veya yinelenen hesap var.');
    codes.add(account.code);
  }
  const numbers = new Set();
  for (const voucher of data.vouchers) {
    if (!voucher.id || !Number.isInteger(voucher.number) || numbers.has(voucher.number) ||
        !/^2026-\d{2}-\d{2}$/.test(voucher.date) || !Array.isArray(voucher.lines))
      throw new Error('Yedekte geçersiz fiş var.');
    numbers.add(voucher.number);
    for (const line of voucher.lines) {
      if (!codes.has(line.code) || !Number.isSafeInteger(line.debit) || line.debit < 0 ||
          !Number.isSafeInteger(line.credit) || line.credit < 0)
        throw new Error('Yedekte geçersiz fiş satırı var.');
    }
    if (validateVoucher(voucher, data.accounts).length)
      throw new Error(`${voucher.number} numaralı fiş yedekte geçersiz veya dengesiz.`);
  }
  return data;
}


